const cmds = [
  ["pr", "gh pr view 2189 --repo entireio/cli --json number,title,body,author,baseRefName,baseRefOid,headRefName,headRefOid,isDraft,mergeable,reviewDecision,url,commits,files"],
  ["reviews", "gh api repos/entireio/cli/pulls/2189/reviews --jq '.[] | {author: .user.login, state: .state, submitted_at: .submitted_at, body: .body}'"],
  ["inline", "gh api repos/entireio/cli/pulls/2189/comments --jq '.[] | {id: .id, user: .user.login, path: .path, line: .line, original_line: .original_line, created_at: .created_at, body: .body, in_reply_to_id: .in_reply_to_id}'"],
  ["conversation", "gh api repos/entireio/cli/issues/2189/comments --jq '.[] | {user: .user.login, created_at: .created_at, body: .body}'"],
  ["checks", "gh pr checks 2189 --repo entireio/cli"]
];
const out = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/remove-stale-agent-rewind-code", yield_time_ms:30000, max_output_tokens:30000});
  return `### ${name}\nexit=${r.exit_code}\n${r.output}`;
}));
out.forEach(text);

const r = await tools.exec_command({cmd:"gh pr view 2189 --repo entireio/cli --json number,title,body,author,baseRefName,baseRefOid,headRefName,headRefOid,isDraft,mergeable,reviewDecision,url,commits,files
gh api repos/entireio/cli/pulls/2189/reviews --jq '.[] | {author: .user.login, state: .state, submitted_at: .submitted_at, body: .body}'
