text(r.output);

const jobs = [
  ["scope", "git rev-parse HEAD\ngit rev-parse upstream/main\ngit merge-base 5ad823b4a32c901d6cdb1df65b3f489d46038f65 HEAD\ngit rev-list --count 5ad823b4a32c901d6cdb1df65b3f489d46038f65..HEAD\ngit diff --stat 5ad823b4a32c901d6cdb1df65b3f489d46038f65..HEAD\ngit log --oneline --decorate 5ad823b4a32c901d6cdb1df65b3f489d46038f65..HEAD"],
  ["diff", "git diff --find-renames --find-copies 5ad823b4a32c901d6cdb1df65b3f489d46038f65..HEAD -- cmd/entire/cli/agent/claudecode/claude.go cmd/entire/cli/agent/codex/codex.go cmd/entire/cli/agent/codex/security_contract_test.go cmd/entire/cli/agent/copilotcli/security_contract_test.go cmd/entire/cli/agent/opencode/opencode.go cmd/entire/cli/integration_test/agent_test.go"],
  ["checkpoint", "entire checkpoint explain --checkpoint 01M1BPH5AYW3XFKN7R858PA7BD --json --no-pager"],
  ["session", "entire session current --json"],
  ["dirty", "git diff HEAD --stat\ngit diff HEAD -- .entire/settings.json"]
];
const out = await Promise.all(jobs.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/remove-stale-agent-rewind-code", yield_time_ms:30000, max_output_tokens:40000});
  return `### ${name}\nexit=${r.exit_code}\n${r.output}`;
}));
out.forEach(text);

