121	// ReadSession reads a session from Claude's storage (JSONL transcript file).
122	// The session data is stored in NativeData as raw JSONL bytes.
123	// ModifiedFiles is computed by parsing the transcript.
124	func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
125		if input.SessionRef == "" {
126			return nil, errors.New("session reference (transcript path) is required")
127		}
128	
129		// Read the raw JSONL file
130		data, err := os.ReadFile(input.SessionRef)
131		if err != nil {
132			return nil, fmt.Errorf("failed to read transcript: %w", err)
133		}
134	
135		// Parse to extract computed fields
136		lines, err := transcript.ParseFromBytes(data)
137		if err != nil {
138			return nil, fmt.Errorf("failed to parse transcript: %w", err)
139		}
140	
141		return &agent.AgentSession{
142			SessionID:     input.SessionID,
143			AgentName:     c.Name(),
144			SessionRef:    input.SessionRef,
145			StartTime:     time.Now(),
146			NativeData:    data,
147			ModifiedFiles: ExtractModifiedFiles(lines),
148		}, nil
149	}
150	
151	// WriteSession writes a session to Claude's storage (JSONL transcript file).
152	// Uses the NativeData field which contains raw JSONL bytes.
153	// The session must have been created by Claude Code (AgentName check).
154	func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
155		if session == nil {
156			return errors.New("session is nil")
157		}
158	
159		// Verify this session belongs to Claude Code
160		if session.AgentName != "" && session.AgentName != c.Name() {
161			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
162		}
163	
164		if session.SessionRef == "" {
165			return errors.New("session reference (transcript path) is required")
166		}
167	
168		if len(session.NativeData) == 0 {
169			return errors.New("session has no native data to write")
170		}
171	
172		// Write the raw JSONL data
173		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
174			return fmt.Errorf("failed to write transcript: %w", err)
175		}
176	
177		return nil
178	}
179	
180	// FormatResumeCommand returns the command to resume a Claude Code session.
181	func (c *ClaudeCodeAgent) FormatResumeCommand(sessionID string) string {
182		return "claude -r " + sessionID
183	}
184	
185	// Session helper methods - work on AgentSession with Claude's native JSONL data
186	
187	// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
188	// Requires NativeData to be populated.
189	func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
190		if session == nil {
191			return nil, errors.New("session is nil")
192		}
193	
194		if len(session.NativeData) == 0 {
195			return nil, errors.New("session has no native data")
196		}
197	
198		if uuid == "" {
199			// No truncation needed, return copy
200			return &agent.AgentSession{
201				SessionID:     session.SessionID,
202				AgentName:     session.AgentName,
203				RepoPath:      session.RepoPath,
204				SessionRef:    session.SessionRef,
205				StartTime:     session.StartTime,
206				NativeData:    session.NativeData,
207				ModifiedFiles: session.ModifiedFiles,
208			}, nil
209		}
210	
211		// Parse, truncate, re-serialize
212		lines, err := transcript.ParseFromBytes(session.NativeData)
213		if err != nil {
214			return nil, fmt.Errorf("failed to parse transcript: %w", err)
215		}
216	
217		truncated := TruncateAtUUID(lines, uuid)
218	
219		newData, err := SerializeTranscript(truncated)
220		if err != nil {
221			return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
222		}
223	
224		return &agent.AgentSession{
225			SessionID:     session.SessionID,
226			AgentName:     session.AgentName,
227			RepoPath:      session.RepoPath,
228			SessionRef:    session.SessionRef,
229			StartTime:     session.StartTime,
230			NativeData:    newData,
231			ModifiedFiles: ExtractModifiedFiles(truncated),
232		}, nil
233	}
234	
235	// ReadSessionFromPath is a convenience method that reads a session directly from a file path.
236	// This is useful when you have the path but not a HookInput.
237	func (c *ClaudeCodeAgent) ReadSessionFromPath(transcriptPath, sessionID string) (*agent.AgentSession, error) {
238		return c.ReadSession(&agent.HookInput{
239			SessionID:  sessionID,
240			SessionRef: transcriptPath,
241		})
242	}
243	
244	// SanitizePathForClaude converts a path to Claude's project directory format.
245	// Claude replaces any non-alphanumeric character with a dash.
246	var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
247	
248	func SanitizePathForClaude(path string) string {
249		return nonAlphanumericRegex.ReplaceAllString(path, "-")
250	}
251	
252	// TranscriptAnalyzer interface implementation
253	
254	// GetTranscriptPosition returns the current line count of a Claude Code transcript.
255	// Claude Code uses JSONL format, so position is the number of lines.
256	// This is a lightweight operation that only counts lines without parsing JSON.
257	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
258	// Returns 0 if the file doesn't exist or is empty.
259	func (c *ClaudeCodeAgent) GetTranscriptPosition(path string) (int, error) {
260		if path == "" {
261			return 0, nil
262		}
263	
264		file, err := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
265		if err != nil {
266			if os.IsNotExist(err) {
267				return 0, nil
268			}
269			return 0, fmt.Errorf("failed to open transcript file: %w", err)
270		}
271		defer file.Close()
272	
273		reader := bufio.NewReader(file)
274		lineCount := 0
275	
276		for {
277			line, err := reader.ReadBytes('\n')
278			if err != nil {
279				if err == io.EOF {
280					if len(line) > 0 {
281						lineCount++ // Count final line without trailing newline
282					}
283					break
284				}
285				return 0, fmt.Errorf("failed to read transcript: %w", err)
286			}
287			lineCount++
288		}
289	
290		return lineCount, nil
291	}
292	
293	// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
294	// For Claude Code (JSONL format), offset is the starting line number.
295	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
296	// Returns:
297	//   - files: list of file paths modified by Claude (from Write/Edit tools)
298	//   - currentPosition: total number of lines in the file
299	//   - error: any error encountered during reading
300	func (c *ClaudeCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
301		if path == "" {
302			return nil, 0, nil
303		}
304	
305		file, openErr := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
306		if openErr != nil {
307			return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
308		}
309		defer file.Close()
310	
311		reader := bufio.NewReader(file)
312		var lines []TranscriptLine
313		lineNum := 0
314	
315		for {
316			lineData, readErr := reader.ReadBytes('\n')
317			if readErr != nil && readErr != io.EOF {
318				return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
319			}
320	
321			if len(lineData) > 0 {
322				lineNum++
323				if lineNum > startOffset {
324					var line TranscriptLine
325					if parseErr := json.Unmarshal(lineData, &line); parseErr == nil {
326						lines = append(lines, line)
327					}
328					// Skip malformed lines silently
329				}
330			}
331	
332			if readErr == io.EOF {
333				break
334			}
335		}
336	
337		return ExtractModifiedFiles(lines), lineNum, nil
338	}
339	
340	// ChunkTranscript splits a JSONL transcript at line boundaries.
341	// Claude Code uses JSONL format (one JSON object per line), so chunking
342	// is done at newline boundaries to preserve message integrity.
343	func (c *ClaudeCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
344		chunks, err := agent.ChunkJSONL(content, maxSize)
345		if err != nil {
346			return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
347		}
348		return chunks, nil
349	}
350	
351	// ReassembleTranscript concatenates JSONL chunks with newlines.
352	//
353	
354	func (c *ClaudeCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
355		return agent.ReassembleJSONL(chunks), nil
356	}
357	
358	// LaunchCmd builds an exec.Cmd for `claude "<initialPrompt>"`. Stdio is wired
359	// to the caller's TTY so the agent runs foreground and the user interacts
360	// normally. The call site is expected to Run() and wait. Hooks inherit the
361	// parent environment.
362	func (c *ClaudeCodeAgent) LaunchCmd(ctx context.Context, initialPrompt string) (*exec.Cmd, error) {
363		bin, err := exec.LookPath("claude")
364		if err != nil {
365			return nil, fmt.Errorf("claude binary not on PATH: %w", err)
366		}
367		cmd := exec.CommandContext(ctx, bin, initialPrompt)
368		cmd.Stdin = os.Stdin
369		cmd.Stdout = os.Stdout
370		cmd.Stderr = os.Stderr
371		cmd.Env = os.Environ()
372		return cmd, nil
373	}

