294	// For Claude Code (JSONL format), offset is the starting line number.
295	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
296	// Returns:
297	//   - files: list of file paths modified by Claude (from Write/Edit tools)
298	//   - currentPosition: total number of lines in the file
299	//   - error: any error encountered during reading
300	func (c *ClaudeCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
301		if path == "" {
302			return nil, 0, nil
303		}
304	
305		file, openErr := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
306		if openErr != nil {
307			return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
308		}
309		defer file.Close()
310	
311		reader := bufio.NewReader(file)
312		var lines []TranscriptLine
313		lineNum := 0
314	
315		for {
316			lineData, readErr := reader.ReadBytes('\n')
317			if readErr != nil && readErr != io.EOF {
318				return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
319			}
