151			SessionID:     input.SessionID,
152			AgentName:     c.Name(),
153			SessionRef:    input.SessionRef,
154			StartTime:     startTime,
155			NativeData:    data,
156			ModifiedFiles: modifiedFiles,
157		}, nil
158	}
