160	// WriteSession writes a session to Codex's storage (JSONL rollout file).
161	func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
162		if session == nil {
163			return errors.New("session is nil")
164		}
165	
166		if session.AgentName != "" && session.AgentName != c.Name() {
167			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
168		}
169	
170		if session.SessionRef == "" {
171			return errors.New("session reference (transcript path) is required")
172		}
173	
174		if len(session.NativeData) == 0 {
175			return errors.New("session has no native data to write")
176		}
177	
178		dataToWrite := SanitizePortableTranscript(session.NativeData)
179		if err := os.WriteFile(session.SessionRef, dataToWrite, 0o600); err != nil {
180			return fmt.Errorf("failed to write transcript: %w", err)
181		}
182	
183		return nil
184	}
