214	func restoredRolloutPath(codexHome, agentSessionID string, startTime time.Time) string {
215		timestamp := startTime.UTC()
216		datePath := filepath.Join(
217			codexHome,
218			timestamp.Format("2006"),
219			timestamp.Format("01"),
220			timestamp.Format("02"),
221		)
222		filename := fmt.Sprintf("rollout-%s-%s.jsonl", timestamp.Format("2006-01-02T15-04-05"), agentSessionID)
223		return filepath.Join(datePath, filename)
224	}
