226	// LaunchCmd builds an exec.Cmd for `codex "<initialPrompt>"`. Stdio is wired
227	// to the caller's TTY so the agent runs foreground and the user interacts
228	// normally. The call site is expected to Run() and wait. Hooks inherit the
229	// parent environment.
230	func (c *CodexAgent) LaunchCmd(ctx context.Context, initialPrompt string) (*exec.Cmd, error) {
231		bin, err := exec.LookPath("codex")
232		if err != nil {
233			return nil, fmt.Errorf("codex binary not on PATH: %w", err)
234		}
235		cmd := exec.CommandContext(ctx, bin, initialPrompt)
236		cmd.Stdin = os.Stdin
237		cmd.Stdout = os.Stdout
238		cmd.Stderr = os.Stderr
239		cmd.Env = os.Environ()
240		return cmd, nil
241	}
