243	func findRolloutBySessionID(codexHome, agentSessionID string) string {
244		if codexHome == "" || validation.ValidateAgentSessionID(agentSessionID) != nil {
245			return ""
246		}
247	
248		patterns := []string{
249			filepath.Join(codexHome, "rollout-*-"+agentSessionID+".jsonl"),
250			filepath.Join(codexHome, "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
251			filepath.Join(filepath.Dir(codexHome), "archived_sessions", "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
252		}
253		for _, pattern := range patterns {
254			matches, err := filepath.Glob(pattern)
255			if err != nil || len(matches) == 0 {
256				continue
257			}
258			// Multiple restored rollouts for the same session ID can exist. Return the
259			// lexicographically latest path so newer dated restores win deterministically.
260			sort.Strings(matches)
261			return matches[len(matches)-1]
262		}
263	
264		return ""
265	}

