  1	// Package opencode implements the Agent interface for OpenCode.
  2	package opencode
  3	
  4	import (
  5		"context"
  6		"encoding/json"
  7		"errors"
  8		"fmt"
  9		"log/slog"
 10		"os"
 11		"path/filepath"
 12		"regexp"
 13		"strings"
 14	
 15		"github.com/entireio/cli/cmd/entire/cli/agent"
 16		"github.com/entireio/cli/cmd/entire/cli/agent/types"
 17		"github.com/entireio/cli/cmd/entire/cli/logging"
 18		"github.com/entireio/cli/cmd/entire/cli/paths"
 19	)
 20	
 21	//nolint:gochecknoinits // Agent self-registration is the intended pattern
 22	func init() {
 23		agent.Register(agent.AgentNameOpenCode, NewOpenCodeAgent)
 24	}
 25	
 26	//nolint:revive // OpenCodeAgent is clearer than Agent in this context
 27	type OpenCodeAgent struct{}
 28	
 29	// NewOpenCodeAgent creates a new OpenCode agent instance.
 30	func NewOpenCodeAgent() agent.Agent {
 31		return &OpenCodeAgent{}
 32	}
 33	
 34	// --- Identity ---
 35	
 36	func (a *OpenCodeAgent) Name() types.AgentName    { return agent.AgentNameOpenCode }
 37	func (a *OpenCodeAgent) Type() types.AgentType    { return agent.AgentTypeOpenCode }
 38	func (a *OpenCodeAgent) Description() string      { return "OpenCode - AI-powered terminal coding agent" }
 39	func (a *OpenCodeAgent) IsPreview() bool          { return true }
 40	func (a *OpenCodeAgent) ProtectedDirs() []string  { return []string{".opencode"} }
 41	func (a *OpenCodeAgent) ProtectedFiles() []string { return []string{"opencode.json"} }
 42	
 43	func (a *OpenCodeAgent) DetectPresence(ctx context.Context) (bool, error) {
 44		repoRoot, err := paths.WorktreeRoot(ctx)
 45		if err != nil {
 46			repoRoot = "."
 47		}
 48		// Check for .opencode directory or opencode.json config
 49		if _, err := os.Stat(filepath.Join(repoRoot, ".opencode")); err == nil {
 50			return true, nil
 51		}
 52		if _, err := os.Stat(filepath.Join(repoRoot, "opencode.json")); err == nil {
 53			return true, nil
 54		}
 55		return false, nil
 56	}
 57	
 58	// --- Transcript Storage ---
 59	
 60	// ReadTranscript reads the transcript for a session.
 61	// The sessionRef is expected to be a path to the export JSON file.
 62	func (a *OpenCodeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 63		data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
 64		if err != nil {
 65			return nil, fmt.Errorf("failed to read opencode transcript: %w", err)
 66		}
 67		return data, nil
 68	}
 69	
 70	// ChunkTranscript splits an OpenCode export JSON transcript by distributing messages across chunks.
 71	// OpenCode uses JSON format with {"info": {...}, "messages": [...]} structure.
 72	func (a *OpenCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 73		var session ExportSession
