    90	// Codex provides the transcript path directly in hook payloads as an absolute path.
    91	// When only a session ID is available, callers recover it from the
    92	// sessions/YYYY/MM/DD/rollout-...-<session-id>.jsonl layout.
    93	func (c *CodexAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
    94		if filepath.IsAbs(agentSessionID) {
    95			return agentSessionID
    96		}
    97		if path := findRolloutBySessionID(sessionDir, agentSessionID); path != "" {
    98			return path
    99		}
   100		if sessionDir != "" {
   101			return filepath.Join(sessionDir, agentSessionID+".jsonl")
   102		}
   103		return agentSessionID
   104	}
